# -*- coding: utf-8 -*-
"""Selwo Sea Terraces: the 268 strings the translation memory did not have.

Same shape as k_atalaya.py and k_higueron.py. Floorplan captions and "Block N, <floor>" labels are
templates; the prose is written by hand. Tokens:  {E464000}  {N65}  {N1.7}  {U} (m2)  {KM}  {G...}.
Run once before assemble.py and once after it (the second run patches the architecture highlights and
keeps unit references and residence names in English).   python3 tools/import/k_selwo.py <scratch dir>
"""
import json, re, sys
SP = sys.argv[1]
LOCS = ['es', 'fr', 'de', 'ru', 'ar', 'nl', 'pl', 'no', 'sv']
todo = list(json.load(open(f'{SP}/import_m/todo.json')))
GROUP = {'es': '.', 'fr': ' ', 'de': '.', 'ru': ' ', 'ar': ',', 'nl': '.', 'pl': ' ', 'no': ' ', 'sv': ' '}
UNIT = {'es': 'm²', 'fr': 'm²', 'de': 'm²', 'ru': 'м²', 'ar': 'م²', 'nl': 'm²', 'pl': 'm²', 'no': 'm²', 'sv': 'm²'}
KM = {'ru': 'км', 'ar': 'كم'}
T = {}


def money(n, l):
    body = f'{n:,}'.replace(',', GROUP[l])
    return f'€ {body}' if l == 'nl' else f'{body} €'


def num(s, l):
    return s.replace(',', GROUP[l]).replace('.', '.' if l == 'ar' else ',')


def expand(text, l):
    text = re.sub(r'\{E(\d+)\}', lambda m: money(int(m.group(1)), l), text)
    text = re.sub(r'\{G(\d+)\}', lambda m: f'{int(m.group(1)):,}'.replace(',', GROUP[l]), text)
    text = re.sub(r'\{N([\d.]+)\}', lambda m: num(m.group(1), l), text)
    return text.replace('{U}', UNIT[l]).replace('{KM}', KM.get(l, 'km'))


def a(i, hint, *tr):
    en = todo[i]
    assert en.startswith(hint), (i, hint, en[:50])
    assert len(tr) == 9, (i, len(tr))
    T[en] = {l: expand(t, l) for l, t in zip(LOCS, tr)}


# ---------------------------------------------------------------- templates
BLOCK = {'es': 'Bloque', 'fr': 'Bloc', 'de': 'Block', 'ru': 'Блок', 'ar': 'مبنى', 'nl': 'Blok', 'pl': 'Blok', 'no': 'Hus', 'sv': 'Hus'}
PART = {   # the labels FLOOR_PARTS already gives each part
    'Ground floor': {'es': 'planta baja', 'fr': 'rez-de-chaussée', 'de': 'Erdgeschoss', 'ru': 'первый этаж', 'ar': 'الطابق الأرضي', 'nl': 'begane grond', 'pl': 'parter', 'no': 'første etasje', 'sv': 'bottenvåning'},
    'First floor': {'es': 'primera planta', 'fr': 'premier étage', 'de': 'erstes Obergeschoss', 'ru': 'второй этаж', 'ar': 'الطابق الأول', 'nl': 'eerste verdieping', 'pl': 'pierwsze piętro', 'no': 'andre etasje', 'sv': 'första våningen'},
    'Penthouse': {'es': 'ático', 'fr': 'penthouse', 'de': 'Penthouse', 'ru': 'пентхаус', 'ar': 'بنتهاوس', 'nl': 'penthouse', 'pl': 'penthouse', 'no': 'toppleilighet', 'sv': 'takvåning'},
    'Duplex penthouse': None, 'Lower level': None, 'Semi-detached villa': None,
}
fp = json.load(open(f'{SP}/import_m/floor_parts.json'))['parts']
for key, fk in (('Duplex penthouse', 'duplex penthouse'), ('Lower level', 'lower level'), ('Semi-detached villa', 'semi-detached villa')):
    PART[key] = {l: fp[fk][l][0].lower() + fp[fk][l][1:] if l != 'de' else fp[fk][l] for l in LOCS}
PART['Ground floor']['de'] = 'Erdgeschoss'
PLAN = {'es': ('Plano del tipo {c}', 'Tipo {c}'), 'fr': ('Plan du type {c}', 'Type {c}'), 'de': ('Grundriss Typ {c}', 'Typ {c}'),
        'ru': ('Планировка типа {c}', 'Тип {c}'), 'ar': ('مخطط النوع {c}', 'النوع {c}'), 'nl': ('Plattegrond van type {c}', 'Type {c}'),
        'pl': ('Rzut typu {c}', 'Typ {c}'), 'no': ('Plantegning type {c}', 'Type {c}'), 'sv': ('Planritning typ {c}', 'Typ {c}')}
SUFFIX = {  # ", ground floor" / ", first floor and solarium"
    'ground floor': {'es': 'planta baja', 'fr': 'rez-de-chaussée', 'de': 'Erdgeschoss', 'ru': 'первый этаж', 'ar': 'الطابق الأرضي', 'nl': 'begane grond', 'pl': 'parter', 'no': 'første etasje', 'sv': 'bottenvåning'},
    'first floor and solarium': {'es': 'primera planta y solárium', 'fr': 'premier étage et solarium', 'de': 'erstes Obergeschoss und Solarium', 'ru': 'второй этаж и солярий', 'ar': 'الطابق الأول والسولاريوم', 'nl': 'eerste verdieping en solarium', 'pl': 'pierwsze piętro i solarium', 'no': 'andre etasje og solterrasse', 'sv': 'första våningen och solterrass'},
}
for en in todo:
    m = re.fullmatch(r'Floorplan of type (\w+)(?:, (ground floor|first floor and solarium))?', en)
    c = re.fullmatch(r'Type (\w+)(?:, (ground floor|first floor and solarium))?', en)
    f = re.fullmatch(r'Block (\w+), (Ground floor|First floor|Penthouse|Duplex penthouse|Lower level|Semi-detached villa)', en)
    if m or c:
        mm = m or c
        k = 0 if m else 1
        T[en] = {l: PLAN[l][k].format(c=mm.group(1)) + (f', {SUFFIX[mm.group(2)][l]}' if mm.group(2) else '') for l in LOCS}
    elif f:
        T[en] = {l: f'{BLOCK[l]} {f.group(1)}, {PART[f.group(2)][l]}' for l in LOCS}

# ---------------------------------------------------------------- names, card, images
a(0, 'Selwo Sea Terraces', *(['Selwo Sea Terraces'] * 9))
a(1, 'Selwo Sea<br>', *(['Selwo Sea<br><em>Terraces</em>'] * 9))
